using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the API key via 'AI:ApiKey' config or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteStore>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var noteStore = host.Services.GetRequiredService<NoteStore>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the web_search tool multiple times with different queries to gather information.
        2. Use the add_note tool to record key findings as you go.
        3. Once you have gathered enough information (at least 3-5 searches), use get_notes to review your notes.
        4. Provide a comprehensive summary of your research findings.
        Be thorough and search for different angles of the topic.
        """,
};

var tools = AIFunctionFactory.Create(researchTools);
tools.AddRange(AIFunctionFactory.Create(noteStore));

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research (or 'quit' to exit): ");

while (Console.ReadLine() is { } topic && !topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(topic))
    {
        Console.Write("\nEnter a topic: ");
        continue;
    }

    noteStore.Clear();
    Console.WriteLine($"\nResearching: {topic}\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    };

    await foreach (var message in agent.InvokeStreamingAsync(messages, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");
    Console.Write("Enter a topic to research (or 'quit' to exit): ");
}

/// <summary>Tools for searching the web.</summary>
public sealed class ResearchTools
{
    private static readonly HttpClient s_http = new();

    [Description("Searches the web for the given query and returns a summary of results. Use this to gather information about a topic.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  [Searching: \"{query}\"]");

        try
        {
            // Use Wikipedia API as a free, no-key search source
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=3&format=json";
            var json = await s_http.GetStringAsync(url, cancellationToken);
            return json;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Tools for taking and reviewing notes during research.</summary>
public sealed class NoteStore
{
    private readonly List<string> _notes = [];

    [Description("Adds a research note. Use this to record key findings during research.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note #{_notes.Count} saved]");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all notes taken so far. Use this to review findings before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return string.Join("\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }

    public void Clear() => _notes.Clear();
}

