using System.Reflection;

// Check MEAI AIFunctionFactory
var meaiAsm = AppDomain.CurrentDomain.GetAssemblies()
    .FirstOrDefault(a => a.GetName().Name == "Microsoft.Extensions.AI")
    ?? Assembly.Load("Microsoft.Extensions.AI");

var factory = meaiAsm.GetTypes().FirstOrDefault(t => t.Name == "AIFunctionFactory");
if (factory != null)
{
    Console.WriteLine($"=== {factory.FullName} ===");
    foreach (var m in factory.GetMethods(BindingFlags.Public | BindingFlags.Static))
        Console.WriteLine($"  static {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
}

// Check ChatResponse/AgentResponse
var agentAsm = Assembly.Load("Microsoft.Agents.AI");
foreach (var t in agentAsm.GetExportedTypes().Where(t => t.Name.Contains("Response") || t.Name.Contains("Result")).OrderBy(t => t.Name))
{
    Console.WriteLine($"\n=== {t.FullName} ===");
    foreach (var p in t.GetProperties())
        Console.WriteLine($"  {p.PropertyType.Name} {p.Name}");
}
